import { gql } from '@apollo/client'

export const REGISTER_PATIENT_MUTATION = gql`
  mutation RegisterPatient($input: CreatePatientInput!) {
    createPatient(input: $input) {
      status
      message
      data {
        id
        visitDate
        status
        patient {
          id
          firstName
          lastName
          middleName
          gender
          dateOfBirth
          primaryPhoneNumber
          alternativePhone
          village
          city
          district
          postalAddress
          nationalIdNumber
          passportNumber
          emergencyContactName
          emergencyContactRelationship
          emergencyContactPhoneNumber
          createdAt
          updatedAt
        }
        linkedInsurances {
          id
          insuranceCardNumber
          patientSharePercentage
          deactivated
          principalMember
          principalMemberName
          principalMemberPhoneNumber
          validFrom
          validUntil
          insuranceProvider {
            id
            insuranceName
            acronym
            coverages {
              id
              insuranceProviderId
              insuranceProviderName
              departmentId
              departmentName
              encounterType
              patientSharePercentage
              createdAt
              updatedAt
            }
          }
        }
      }
    }
  }
`

export const CREATE_PATIENT_INSURANCE_MUTATION = gql`
  mutation CreatePatientInsurance($input: CreatePatientInsuranceInput!) {
    createPatientInsurance(input: $input) {
      status
      message
      data {
        id
        insuranceCardNumber
          patientSharePercentage
          deactivated
        principalMember
        principalMemberName
        principalMemberPhoneNumber
        validFrom
        validUntil
      }
    }
  }
`

export const UPDATE_PATIENT_INSURANCE_MUTATION = gql`
  mutation UpdatePatientInsurance($patientInsuranceId: ID!, $input: UpdatePatientInsuranceInput!) {
    updatePatientInsurance(patientInsuranceId: $patientInsuranceId, input: $input) {
      status
      message
      data {
        id
        insuranceCardNumber
          patientSharePercentage
          deactivated
        principalMember
        principalMemberName
        principalMemberPhoneNumber
        validFrom
        validUntil
      }
    }
  }
`

export const UPDATE_PATIENT_MUTATION = gql`
  mutation UpdatePatient($patientId: ID!, $input: UpdatePatientInput!) {
    updatePatient(patientId: $patientId, input: $input) {
      status
      message
      data {
        id
        firstName
        lastName
        middleName
        gender
        dateOfBirth
        primaryPhoneNumber
        alternativePhone
        village
        city
        district
        postalAddress
        nationalIdNumber
        passportNumber
        emergencyContactName
        emergencyContactRelationship
        emergencyContactPhoneNumber
        createdAt
        updatedAt
      }
    }
  }
`

export const DELETE_PATIENT_INSURANCE_MUTATION = gql`
  mutation DeletePatientInsurance($patientInsuranceId: ID!) {
    deletePatientInsurance(patientInsuranceId: $patientInsuranceId) {
      status
      message
      data
    }
  }
`


