export function useAddActionToVisitDepartment() {
  const { doctor } = useAuth();
  const [mutation, { loading, error }] = useMutation(
    ADD_PRODUCT_TO_VISIT_DEPARTMENT_MUTATION,
    {
      refetchQueries: visitRefetchQueries,
      awaitRefetchQueries: true,
    },
  );

  const addAction = async (
    visitId: string,
    departmentId: string,
    actionId: string,
    quantity?: number,
    processorId?: string,
  ): Promise<ApiResponse<any>> => {
    try {
      const effectiveProcessorId = processorId || doctor?.id;
      const result = await mutation({
        variables: {
          input: {
            visitId,
            departmentId,
            productId: actionId,
            quantity: quantity ?? 1,
            status: "PENDING",
            ...(effectiveProcessorId ? { processorId: effectiveProcessorId } : {}),
          },
        },
      });
      const payload = result.data?.addVisitDepartmentProduct;
      return {
        status: payload?.status || "ERROR",
        messages: payload?.message
          ? [{ text: payload.message, type: payload.status || "ERROR" }]
          : undefined,
        data: payload?.data
          ? mapGqlVisitDepartment(payload.data)
          : undefined,
      };
    } catch (err) {
      console.error("Add action error:", err);
      throw err;
    }
  };

  return { addAction, loading, error };
}

